function fsmParse(text){
  var lines=String(text).replace(/\r/g,'').split('\n').map(function(s){ return s.trim(); }).filter(Boolean);
  if(!lines.length) return { value:null, error:'定义为空' };
  var trans={}, states={}, finals={}, initial=null;
  for(var i=0;i<lines.length;i++){
    var p=lines[i].split(',').map(function(s){ return s.trim(); });
    if(p.length!==3||!p[0]||!p[1]||!p[2]) return { value:null, error:'第 '+(i+1)+' 行需 from,event,to' };
    var from=p[0].replace(/^\*/,''), ev=p[1], toRaw=p[2], to=toRaw.replace(/^\*/,'');
    if(p[0][0]==='*') finals[from]=true;
    if(toRaw[0]==='*') finals[to]=true;
    if(initial===null) initial=from;
    states[from]=true; states[to]=true;
    trans[from]=trans[from]||{};
    if(trans[from][ev]!==undefined && trans[from][ev]!==to)
      return { value:null, error:'第 '+(i+1)+' 行: 状态 '+from+' 的事件 '+ev+' 已指向 '+trans[from][ev]+'（非确定）' };
    trans[from][ev]=to;
  }
  return { value:{ initial:initial, states:Object.keys(states).sort(),
    finals:Object.keys(finals).sort(), trans:trans }, error:null };
}
function fsmReachable(fsm){
  var seen={}, queue=[fsm.initial];
  seen[fsm.initial]=true;
  while(queue.length){
    var s=queue.shift(), t=fsm.trans[s]||{};
    for(var ev in t){ if(!seen[t[ev]]){ seen[t[ev]]=true; queue.push(t[ev]); } }
  }
  var unreachable=fsm.states.filter(function(s){ return !seen[s]; });
  return { value:{ reachable:Object.keys(seen).sort(), unreachable:unreachable }, error:null };
}
function fsmDeadStates(fsm){
  // dead = non-final state with no outgoing transitions, or state that cannot reach any final
  var canReachFinal={};
  fsm.finals.forEach(function(f){ canReachFinal[f]=true; });
  var changed=true;
  while(changed){
    changed=false;
    for(var s in fsm.trans){
      if(canReachFinal[s]) continue;
      for(var ev in fsm.trans[s]){
        if(canReachFinal[fsm.trans[s][ev]]){ canReachFinal[s]=true; changed=true; break; }
      }
    }
  }
  var dead=fsm.states.filter(function(s){ return !canReachFinal[s]; });
  return { value:dead, error:null };
}
function fsmRun(fsm, events){
  if(!Array.isArray(events)) return { value:null, error:'事件必须是数组' };
  var cur=fsm.initial, path=[cur];
  for(var i=0;i<events.length;i++){
    var t=fsm.trans[cur]||{};
    if(t[events[i]]===undefined)
      return { value:null, error:'状态 '+cur+' 无事件 "'+events[i]+'"（第 '+(i+1)+' 步），可用: '+(Object.keys(t).join(', ')||'无') };
    cur=t[events[i]];
    path.push(cur);
  }
  return { value:{ path:path, end:cur, accepted:fsm.finals.indexOf(cur)>=0 }, error:null };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { fsmParse:fsmParse, fsmReachable:fsmReachable, fsmDeadStates:fsmDeadStates, fsmRun:fsmRun };
}
if (typeof window !== 'undefined') {
  window.StateForgePure = { fsmParse:fsmParse, fsmReachable:fsmReachable, fsmDeadStates:fsmDeadStates, fsmRun:fsmRun };
}
